// Simple running counters for human-friendly invoice/offer IDs
function nextSequence(db, key) {
  db.sequences = db.sequences || {};
  db.sequences[key] = (db.sequences[key] || 0) + 1;
  return db.sequences[key];
}

function authMiddleware(req, res, next) {
  const header = req.headers.authorization;
  if (!header) return res.status(401).json({ error: 'Not authenticated' });
  const token = header.replace('Bearer ', '');
  try {
    req.userEmail = jwt.verify(token, JWT_SECRET).email;
    next();
  } catch (e) {
    return res.status(401).json({ error: 'Invalid or expired session, please log in again' });
  }
}

