// ---------- Auth ----------
app.post('/api/signup', (req, res) => {
  const { name, email, password } = req.body || {};
  if (!name || !email || !password) return res.status(400).json({ error: 'Name, email, and password are all required' });
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim())) return res.status(400).json({ error: 'Please enter a valid email address' });
  if (password.length < 6) return res.status(400).json({ error: 'Password must be at least 6 characters' });

  const db = readDB();
  const normalizedEmail = email.toLowerCase().trim();
  if (db.users.find(u => u.email === normalizedEmail)) {
    return res.status(400).json({ error: 'An account with this email already exists' });
  }
  const user = { name: name.trim(), email: normalizedEmail, password: bcrypt.hashSync(password, 10), enrolled: [] };
  db.users.push(user);
  writeDB(db);

  const token = jwt.sign({ email: normalizedEmail }, JWT_SECRET, { expiresIn: '7d' });
  res.json({ token, name: user.name });
});

app.post('/api/login', (req, res) => {
  const { email, password } = req.body || {};
  const db = readDB();
  const normalizedEmail = (email || '').toLowerCase().trim();
  const user = db.users.find(u => u.email === normalizedEmail);
  if (!user || !bcrypt.compareSync(password || '', user.password)) {
    return res.status(401).json({ error: 'Incorrect email or password' });
  }
  const token = jwt.sign({ email: user.email }, JWT_SECRET, { expiresIn: '7d' });
  res.json({ token, name: user.name });
});

app.get('/api/me', authMiddleware, (req, res) => {
  const db = readDB();
  const user = db.users.find(u => u.email === req.userEmail);
  if (!user) return res.status(404).json({ error: 'User not found' });
  if (!Array.isArray(user.enrolled)) user.enrolled = [];
  user.enrolled = user.enrolled.map(e => (typeof e === 'string' ? { courseId: e, progress: { completed: [] }, offerLetter: null, certificate: null } : e));
  res.json({ name: user.name, email: user.email, enrolled: user.enrolled });
});

// ---------- Checkout (Razorpay) ----------
app.post('/api/checkout/create-order', authMiddleware, async (req, res) => {
  const { courseId } = req.body || {};
  const course = COURSES.find(c => c.id === courseId);
  if (!course) return res.status(404).json({ error: 'Course not found' });
  if (!razorpayConfigured) {
    return res.status(500).json({ error: 'Razorpay is not configured yet. Add RAZORPAY_KEY_ID and RAZORPAY_KEY_SECRET to your .env file.' });
  }
  try {
    const order = await razorpay.orders.create({
      amount: course.price * 100, // Razorpay expects paise
      currency: 'INR',
      receipt: `receipt_${courseId}_${Date.now()}`,
    });
    res.json({ orderId: order.id, amount: order.amount, currency: order.currency, keyId: process.env.RAZORPAY_KEY_ID, course });
  } catch (e) {
    const detail = e?.error?.description || e?.message || JSON.stringify(e);
    console.error('[checkout/create-order] Razorpay order creation failed:', detail);
    res.status(500).json({ error: 'Could not create Razorpay order', detail });
  }
});

app.post('/api/checkout/verify', authMiddleware, async (req, res) => {
  const { razorpay_order_id, razorpay_payment_id, razorpay_signature, courseId } = req.body || {};
  if (!razorpayConfigured) return res.status(500).json({ error: 'Razorpay is not configured yet' });

  const course = COURSES.find(c => c.id === courseId);
  if (!course) return res.status(404).json({ error: 'Course not found' });

  const expectedSignature = crypto
    .createHmac('sha256', process.env.RAZORPAY_KEY_SECRET)
    .update(`${razorpay_order_id}|${razorpay_payment_id}`)
    .digest('hex');

  if (expectedSignature !== razorpay_signature) {
    return res.status(400).json({ error: 'Payment verification failed — signature mismatch' });
  }

  const db = readDB();
  const user = db.users.find(u => u.email === req.userEmail);
  if (!user) return res.status(404).json({ error: 'User not found' });

  if (!Array.isArray(user.enrolled)) user.enrolled = [];
  // Migrate any legacy plain-string enrollments (from before this schema existed)
  user.enrolled = user.enrolled.map(e => (typeof e === 'string' ? { courseId: e } : e));

  let enrollment = user.enrolled.find(e => e.courseId === courseId);
  if (!enrollment) {
    enrollment = {
      courseId,
      enrolledAt: new Date().toISOString(),
      progress: { completed: [] },
      offerLetter: null,
      certificate: null,
    };
    user.enrolled.push(enrollment);
  }

  const invoiceNumber = `INV-${new Date().getFullYear()}-${String(nextSequence(db, 'invoice')).padStart(5, '0')}`;
  writeDB(db);

  // Email the invoice. The offer letter is generated separately, on-demand,
  // once the student fills in their own details via /api/offer-letter —
  // not auto-created here.
  let emailStatus = { invoice: null };
  try {
    const invoicePdf = await generateInvoicePDF({
      invoiceNumber,
      date: new Date().toLocaleDateString('en-IN'),
      studentName: user.name,
      studentEmail: user.email,
      courseName: course.name,
      amount: course.price,
    });

    emailStatus = await sendEmail({
      to: user.email,
      subject: `Your ${course.name} enrollment — invoice attached`,
      html: `<p>Hi ${user.name},</p><p>Thanks for enrolling in <b>${course.name}</b>. Your invoice is attached.</p>` +
        (course.type === 'internship'
          ? `<p>Head to your dashboard to start learning, and generate your official offer letter whenever you're ready — it only takes a minute.</p>`
          : ``),
      attachments: [{ filename: `${invoiceNumber}.pdf`, content: invoicePdf }],
    });
  } catch (e) {
    console.error('[checkout] Failed to generate/send invoice:', e.message);
    emailStatus = { sent: false, reason: e.message };
  }

  res.json({ success: true, invoiceNumber, email: emailStatus });
});

// ---------- Enrollment progress ----------
function findUserAndEnrollment(email, courseId) {
  const db = readDB();
  const user = db.users.find(u => u.email === email);
  if (!user) return { db, user: null, enrollment: null };
  if (!Array.isArray(user.enrolled)) user.enrolled = [];
  user.enrolled = user.enrolled.map(e => (typeof e === 'string' ? { courseId: e } : e));
  const enrollment = user.enrolled.find(e => e.courseId === courseId);
  return { db, user, enrollment };
}

app.get('/api/enrollment/:courseId', authMiddleware, (req, res) => {
  const { user, enrollment } = findUserAndEnrollment(req.userEmail, req.params.courseId);
  if (!user) return res.status(404).json({ error: 'User not found' });
  if (!enrollment) return res.status(403).json({ error: 'You are not enrolled in this course' });
  res.json(enrollment);
});

app.post('/api/progress', authMiddleware, (req, res) => {
  const { courseId, lessonKey } = req.body || {};
  if (!courseId || !lessonKey) return res.status(400).json({ error: 'courseId and lessonKey are required' });
  const { db, user, enrollment } = findUserAndEnrollment(req.userEmail, courseId);
  if (!user) return res.status(404).json({ error: 'User not found' });
  if (!enrollment) return res.status(403).json({ error: 'You are not enrolled in this course' });

  enrollment.progress = enrollment.progress || { completed: [] };
  if (!enrollment.progress.completed.includes(lessonKey)) {
    enrollment.progress.completed.push(lessonKey);
  }
  writeDB(db);
  res.json({ success: true, completed: enrollment.progress.completed });
});

// Exact day-span expected for a given duration string, e.g. "4 weeks" -> 28 days
function expectedDurationDays(durationText) {
  const match = /(\d+)\s*weeks?/i.exec(durationText || '');
  const weeks = match ? parseInt(match[1], 10) : 4;
  return weeks * 7;
}

function parseDateOnly(str) {
  // Expects 'YYYY-MM-DD'; returns a UTC midnight Date, or null if invalid
  if (!/^\d{4}-\d{2}-\d{2}$/.test(str || '')) return null;
  const d = new Date(str + 'T00:00:00Z');
  return isNaN(d.getTime()) ? null : d;
}

function validateInternshipDates(startStr, endStr, durationText) {
  const start = parseDateOnly(startStr);
  const end = parseDateOnly(endStr);
  if (!start || !end) return 'Start and end dates must be valid dates (YYYY-MM-DD)';

  const today = new Date();
  const todayUTC = new Date(Date.UTC(today.getFullYear(), today.getMonth(), today.getDate()));
  if (end.getTime() > todayUTC.getTime()) return 'End date cannot be in the future';
  if (start.getTime() > end.getTime()) return 'Start date must be before end date';

  const diffDays = Math.round((end.getTime() - start.getTime()) / 86400000);
  const expected = expectedDurationDays(durationText);
  // Allow a small tolerance (+/- 2 days) for calendar-month vs. week-count rounding
  if (Math.abs(diffDays - expected) > 2) {
    return `The gap between start and end date must match the internship duration (${durationText}, ~${expected} days). Yours is ${diffDays} days.`;
  }
  return null;
}

function validateFormFields(body) {
  const required = ['name', 'email', 'contact', 'college', 'regNo', 'startDate', 'endDate'];
  for (const field of required) {
    if (!body[field] || !String(body[field]).trim()) return `${field} is required`;
  }
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(body.email.trim())) return 'Please enter a valid email address';
  if (!/^[0-9+\-\s]{7,15}$/.test(body.contact.trim())) return 'Please enter a valid contact number';
  return null;
}

// ---------- Offer letter (one-time, student-filled, locked after submit) ----------
app.post('/api/offer-letter', authMiddleware, async (req, res) => {
  const { courseId, name, email, contact, college, regNo, startDate, endDate, paymentProof } = req.body || {};
  if (!courseId) return res.status(400).json({ error: 'courseId is required' });

  const course = COURSES.find(c => c.id === courseId);
  if (!course) return res.status(404).json({ error: 'Course not found' });

  const { db, user, enrollment } = findUserAndEnrollment(req.userEmail, courseId);
  if (!user) return res.status(404).json({ error: 'User not found' });
  if (!enrollment) return res.status(403).json({ error: 'You must be enrolled (and have paid) to generate an offer letter' });
  if (enrollment.offerLetter) return res.status(400).json({ error: 'An offer letter has already been generated for this enrollment and cannot be regenerated' });

  const fieldError = validateFormFields(req.body || {});
  if (fieldError) return res.status(400).json({ error: fieldError });
  if (!paymentProof) return res.status(400).json({ error: 'Please attach a screenshot of your payment confirmation' });

  const dateError = validateInternshipDates(startDate, endDate, course.duration);
  if (dateError) return res.status(400).json({ error: dateError });

  const offerId = `BF-OFR-${new Date().getFullYear()}-${String(nextSequence(db, 'offer')).padStart(5, '0')}`;
  const issuedDate = new Date().toLocaleDateString('en-IN');
  const fmt = (s) => new Date(s + 'T00:00:00Z').toLocaleDateString('en-IN', { timeZone: 'UTC' });

  let pdfBuffer;
  try {
    pdfBuffer = await generateOfferLetterPDF({
      offerId,
      studentName: name.trim(),
      email: email.trim(),
      contact: contact.trim(),
      college: college.trim(),
      regNo: regNo.trim(),
      courseName: course.name,
      startDate: fmt(startDate),
      endDate: fmt(endDate),
      duration: course.duration,
      issuedDate,
    });
  } catch (e) {
    console.error('[offer-letter] PDF generation failed:', e.message);
    return res.status(500).json({ error: 'Could not generate the offer letter PDF' });
  }

  enrollment.offerLetter = {
    id: offerId,
    submittedAt: new Date().toISOString(),
    name: name.trim(), email: email.trim(), contact: contact.trim(),
    college: college.trim(), regNo: regNo.trim(),
    startDate, endDate,
  };
  writeDB(db);

  const emailStatus = await sendEmail({
    to: email.trim(),
    subject: `Your ${course.name} internship offer letter — ${offerId}`,
    html: `<p>Hi ${name.trim()},</p><p>Congratulations! Your internship offer letter for <b>${course.name}</b> is attached.</p><p>Offer Letter ID: <b>${offerId}</b></p>`,
    attachments: [{ filename: `${offerId}.pdf`, content: pdfBuffer }],
  });

  res.json({ success: true, offerId, email: emailStatus });
});

// ---------- Completion certificate (one-time, requires offer letter first) ----------
app.post('/api/certificate', authMiddleware, async (req, res) => {
  const { courseId, name, email, contact, college, regNo, startDate, endDate, paymentProof } = req.body || {};
  if (!courseId) return res.status(400).json({ error: 'courseId is required' });

  const course = COURSES.find(c => c.id === courseId);
  if (!course) return res.status(404).json({ error: 'Course not found' });

  const { db, user, enrollment } = findUserAndEnrollment(req.userEmail, courseId);
  if (!user) return res.status(404).json({ error: 'User not found' });
  if (!enrollment) return res.status(403).json({ error: 'You must be enrolled (and have paid) to generate a certificate' });
  if (!enrollment.offerLetter) return res.status(400).json({ error: 'Generate your offer letter first, then you can claim your completion certificate' });
  if (enrollment.certificate) return res.status(400).json({ error: 'A certificate has already been generated for this enrollment and cannot be regenerated' });

  const fieldError = validateFormFields(req.body || {});
  if (fieldError) return res.status(400).json({ error: fieldError });
  if (!paymentProof) return res.status(400).json({ error: 'Please attach a screenshot of your payment confirmation' });

  const dateError = validateInternshipDates(startDate, endDate, course.duration);
  if (dateError) return res.status(400).json({ error: dateError });

  const certId = `BF-CERT-${new Date().getFullYear()}-${String(nextSequence(db, 'certificate')).padStart(5, '0')}`;
  const issuedDate = new Date().toLocaleDateString('en-IN');
  const fmt = (s) => new Date(s + 'T00:00:00Z').toLocaleDateString('en-IN', { timeZone: 'UTC' });

  let pdfBuffer;
  try {
    pdfBuffer = await generateCertificatePDF({
      certId,
      studentName: name.trim(),
      email: email.trim(),
      contact: contact.trim(),
      college: college.trim(),
      regNo: regNo.trim(),
      courseName: course.name,
      startDate: fmt(startDate),
      endDate: fmt(endDate),
      issuedDate,
    });
  } catch (e) {
    console.error('[certificate] PDF generation failed:', e.message);
    return res.status(500).json({ error: 'Could not generate the certificate PDF' });
  }

  enrollment.certificate = {
    id: certId,
    submittedAt: new Date().toISOString(),
    name: name.trim(), email: email.trim(), contact: contact.trim(),
    college: college.trim(), regNo: regNo.trim(),
    startDate, endDate, courseName: course.name,
  };
  writeDB(db);

  const emailStatus = await sendEmail({
    to: email.trim(),
    subject: `Your ${course.name} completion certificate — ${certId}`,
    html: `<p>Hi ${name.trim()},</p><p>Congratulations on completing <b>${course.name}</b>! Your certificate is attached.</p><p>Certificate ID: <b>${certId}</b> — anyone can verify this certificate on our website using this ID or by scanning the QR code on it.</p>`,
    attachments: [{ filename: `${certId}.pdf`, content: pdfBuffer }],
  });

  res.json({ success: true, certId, email: emailStatus });
});

// ---------- Public certificate verification (no auth — anyone, e.g. a college, can check) ----------
app.get('/api/verify/:certId', (req, res) => {
  const db = readDB();
  for (const user of db.users) {
    const enrolled = Array.isArray(user.enrolled) ? user.enrolled : [];
    for (const e of enrolled) {
      if (e.certificate && e.certificate.id === req.params.certId) {
        return res.json({
          valid: true,
          certId: e.certificate.id,
          name: e.certificate.name,
          college: e.certificate.college,
          regNo: e.certificate.regNo,
          courseName: e.certificate.courseName,
          startDate: e.certificate.startDate,
          endDate: e.certificate.endDate,
          issuedAt: e.certificate.submittedAt,
        });
      }
    }
  }
  res.status(404).json({ valid: false, error: 'No certificate found with this ID' });
});

